&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Pragmatism: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Makes practical, data-driven decisions that balance quality, efficiency, cost, and business needs.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Integrity: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Acts honestly and ethically while maintaining confidentiality and compliance with company policies and laws.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Innovation: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Continuously seeks better ideas, technologies, and processes to improve business performance.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Essential Duties &amp;amp; Responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335572079&amp;quot;:8,&amp;quot;335572080&amp;quot;:0,&amp;quot;335572081&amp;quot;:26342,&amp;quot;469789806&amp;quot;:&amp;quot;single&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Lead structural, fatigue, durability, and NVH CAE analysis for battery module and pack designs, including vibration fatigue (random PSD, sine dwell/sweep), weld fatigue (spot, laser, staple, MIG), and thermal cycling creep/fatigue of polymeric components.&lt;/span&gt;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Define and drive the structural/CAE analysis strategy, methods, and technology roadmap across battery engineering programs.&lt;/span&gt;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Develop and implement automation tools and standard engineering work processes to improve CAE modeling quality, efficiency, and repeatability.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Apply optimization, DOE, and AI/ML techniques to guide battery module and pack design decisions.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Partner closely with Design Release Engineers (DREs) and cross-functional teams (mechanical, electrical, systems, manufacturing) to ensure structural designs meet performance, safety, and reliability targets.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Review and validate FEA models, structural calculations, and analysis reports for battery components including trays, cell tabs, BDU, ICB, side plates, and brackets.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Lead root cause investigations of structural failures, test findings, and field issues, and support corrective action development.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Evaluate and implement CAE software/platforms and tools (e.g., ABAQUS, HyperWorks/OptiStruct, NASTRAN, LS-DYNA, ANSA, nCode) to support analysis needs.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Mentor and provide technical leadership to structural and CAE engineers across the team.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Present analysis results, design recommendations, and program-level structural risk assessments to engineering and program leadership.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Support continuous improvement of engineering standards, design practices, and simulation methodology.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Other duties as assigned.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Supervisory Responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335572079&amp;quot;:8,&amp;quot;335572080&amp;quot;:0,&amp;quot;335572081&amp;quot;:26342,&amp;quot;469789806&amp;quot;:&amp;quot;single&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This position does not have direct reports but is expected to provide technical leadership, mentorship, and analysis review guidance to structural and CAE engineers across programs.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Required Qualifications&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335572079&amp;quot;:8,&amp;quot;335572080&amp;quot;:0,&amp;quot;335572081&amp;quot;:26342,&amp;quot;469789806&amp;quot;:&amp;quot;single&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt; PhD or MS in Mechanical Engineering, Structural Engineering, Solid Mechanics, or a related technical discipline.&lt;/span&gt;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• 15+ years of experience in structural, fatigue, and durability CAE analysis, ideally within automotive, battery, or related industrial systems.&lt;/span&gt;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Expert-level proficiency in FEA and CAE tools such as ABAQUS, HyperWorks/OptiStruct, NASTRAN, LS-DYNA, ANSA, and nCode.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Strong background in fatigue, NVH, optimization/DOE, and multi-physics structural analysis.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Proven track record developing CAE automation tools and standard engineering work processes.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Experience with scripting/programming for CAE automation (Python, C/C++, Tcl/Tk, VBA, or similar).&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Demonstrated ability to define technical strategy, mentor engineers, and drive cross-functional collaboration.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;• Excellent written and verbal communication skills, with experience presenting to engineering and program leadership.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Preferred Qualifications&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335572079&amp;quot;:8,&amp;quot;335572080&amp;quot;:0,&amp;quot;335572081&amp;quot;:26342,&amp;quot;469789806&amp;quot;:&amp;quot;single&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
